  `product_sn` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品条码',
  `valid_ind` bit(1) NULL DEFAULT NULL COMMENT '是否有效',
