-- ----------------------------
-- Table structure for sms_seckill_log
-- ----------------------------
DROP TABLE IF EXISTS `sms_seckill_log`;
CREATE TABLE `sms_seckill_log`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `member_id` int NULL DEFAULT NULL COMMENT '会员id',
  `product_id` bigint NULL DEFAULT NULL COMMENT '商品id',
  `member_phone` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会员电话',
  `product_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '商品名称',
  `subscribe_time` datetime NULL DEFAULT NULL COMMENT '会员订阅时间',
  `send_time` datetime NULL DEFAULT NULL COMMENT '发送时间',
  `valid_ind` bit(1) NULL DEFAULT NULL COMMENT '是否有效',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `creator_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updater_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '限时购通知记录表。用于存储会员的限时购预约记录，当有的限时购场次还未开始时，会员可以进行预约操作，当场次开始时，系统会进行提醒。' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sms_seckill_log
-- ----------------------------

-- ----------------------------
-- Table structure for sms_seckill_product
-- ----------------------------
DROP TABLE IF EXISTS `sms_seckill_product`;
CREATE TABLE `sms_seckill_product`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `seckill_id` bigint NULL DEFAULT NULL COMMENT '限时购id',
  `seckill_session_id` bigint NULL DEFAULT NULL COMMENT '编号',
  `product_id` bigint NULL DEFAULT NULL COMMENT '商品id',
  `seckill_price` decimal(10, 2) NULL DEFAULT NULL COMMENT '限时购价格',
  `sku_id` bigint NULL DEFAULT NULL COMMENT 'skuid',
  `seckill_count` int NULL DEFAULT NULL COMMENT '限时购库存数量',
  `seckill_limit` int NULL DEFAULT NULL COMMENT '每人限购数量',
  `sort` int NULL DEFAULT NULL COMMENT '排序',
  `valid_ind` bit(1) NULL DEFAULT NULL COMMENT '是否有效',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `creator_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updater_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '限时购与商品关系表。用于存储与限时购相关的商品信息，一个限时购中有多个场次，每个场次都可以设置不同活动商品。' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sms_seckill_product
-- ----------------------------

-- ----------------------------
-- Table structure for sms_seckill_session
-- ----------------------------
DROP TABLE IF EXISTS `sms_seckill_session`;
CREATE TABLE `sms_seckill_session`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '场次名称',
  `start_time` time NULL DEFAULT NULL COMMENT '每日开始时间',
  `end_time` time NULL DEFAULT NULL COMMENT '每日结束时间',
  `status` int NULL DEFAULT NULL COMMENT '启用状态：0->不启用；1->启用',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `valid_ind` bit(1) NULL DEFAULT NULL COMMENT '是否有效',
  `creator_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `updater_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新人',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '限时购场次表。用于存储限时购场次的信息，在一天中，一个限时购活动会有多个不同的活动时间段。' ROW_FORMAT = DYNAMIC;

